200	    private void realPutBytes(final String key, byte[] value, int saveTime) {
201	        if (value == null) return;
202	        DiskCacheManager diskCacheManager = getDiskCacheManager();
203	        if (diskCacheManager == null) return;
204	        if (saveTime >= 0) value = DiskCacheHelper.newByteArrayWithTime(saveTime, value);
205	        File file = diskCacheManager.getFileBeforePut(key);
206	        UtilsBridge.writeFileFromBytes(file, value);
207	        diskCacheManager.updateModify(file);
208	        diskCacheManager.put(file);
209	    }
