237	    private byte[] realGetBytes(@NonNull final String key, final byte[] defaultValue) {
238	        DiskCacheManager diskCacheManager = getDiskCacheManager();
239	        if (diskCacheManager == null) return defaultValue;
240	        final File file = diskCacheManager.getFileIfExists(key);
241	        if (file == null) return defaultValue;
242	        byte[] data = UtilsBridge.readFile2Bytes(file);
243	        if (DiskCacheHelper.isDue(data)) {
244	            diskCacheManager.removeByKey(key);
245	            return defaultValue;
246	        }
247	        diskCacheManager.updateModify(file);
248	        return DiskCacheHelper.getDataWithoutDueTime(data);
249	    }
