632	                && diskCacheManager.removeByKey(TYPE_JSON_ARRAY + key)
633	                && diskCacheManager.removeByKey(TYPE_BITMAP + key)
634	                && diskCacheManager.removeByKey(TYPE_DRAWABLE + key)
635	                && diskCacheManager.removeByKey(TYPE_PARCELABLE + key)
636	                && diskCacheManager.removeByKey(TYPE_SERIALIZABLE + key);
637	    }
