650	    private static final class DiskCacheManager {
651	        private final AtomicLong      cacheSize;
652	        private final AtomicInteger   cacheCount;
653	        private final long            sizeLimit;
654	        private final int             countLimit;
655	        private final Map<File, Long> lastUsageDates
656	                = Collections.synchronizedMap(new HashMap<File, Long>());
657	        private final File            cacheDir;
658	        private final Thread          mThread;
659	
660	        private DiskCacheManager(final File cacheDir, final long sizeLimit, final int countLimit) {
661	            this.cacheDir = cacheDir;
662	            this.sizeLimit = sizeLimit;
663	            this.countLimit = countLimit;
664	            cacheSize = new AtomicLong();
665	            cacheCount = new AtomicInteger();
666	            mThread = new Thread(new Runnable() {
667	                @Override
668	                public void run() {
669	                    int size = 0;
670	                    int count = 0;
671	                    final File[] cachedFiles = cacheDir.listFiles(new FilenameFilter() {
672	                        @Override
673	                        public boolean accept(File dir, String name) {
674	                            return name.startsWith(CACHE_PREFIX);
675	                        }
676	                    });
677	                    if (cachedFiles != null) {
678	                        for (File cachedFile : cachedFiles) {
679	                            size += cachedFile.length();
680	                            count += 1;
681	                            lastUsageDates.put(cachedFile, cachedFile.lastModified());
682	                        }
683	                        cacheSize.getAndAdd(size);
684	                        cacheCount.getAndAdd(count);
685	                    }
686	                }
687	            });
688	            mThread.start();
689	        }
690	
691	        private long getCacheSize() {
692	            wait2InitOk();
693	            return cacheSize.get();
694	        }
695	
696	        private int getCacheCount() {
697	            wait2InitOk();
698	            return cacheCount.get();
699	        }
700	
701	        private File getFileBeforePut(final String key) {
702	            wait2InitOk();
703	            File file = new File(cacheDir, getCacheNameByKey(key));
704	            if (file.exists()) {
705	                cacheCount.addAndGet(-1);
706	                cacheSize.addAndGet(-file.length());
707	            }
708	            return file;
709	        }
710	
711	        private void wait2InitOk() {
712	            try {
713	                mThread.join();
714	            } catch (InterruptedException e) {
715	                e.printStackTrace();
716	            }
717	        }
718	
719	        private File getFileIfExists(final String key) {
720	            File file = new File(cacheDir, getCacheNameByKey(key));
721	            if (!file.exists()) return null;
722	            return file;
723	        }
724	
725	        private String getCacheNameByKey(final String key) {
726	            return CACHE_PREFIX + key.substring(0, 3) + key.substring(3).hashCode();
727	        }
728	
729	        private void put(final File file) {
730	            cacheCount.addAndGet(1);
731	            cacheSize.addAndGet(file.length());
732	            while (cacheCount.get() > countLimit || cacheSize.get() > sizeLimit) {
733	                cacheSize.addAndGet(-removeOldest());
734	                cacheCount.addAndGet(-1);
735	            }
736	        }
737	
738	        private void updateModify(final File file) {
739	            Long millis = System.currentTimeMillis();
740	            file.setLastModified(millis);
741	            lastUsageDates.put(file, millis);
742	        }
743	
744	        private boolean removeByKey(final String key) {
745	            File file = getFileIfExists(key);
746	            if (file == null) return true;
747	            if (!file.delete()) return false;
748	            cacheSize.addAndGet(-file.length());
749	            cacheCount.addAndGet(-1);
750	            lastUsageDates.remove(file);
751	            return true;
752	        }
753	
754	        private boolean clear() {
755	            File[] files = cacheDir.listFiles(new FilenameFilter() {
756	                @Override
757	                public boolean accept(File dir, String name) {
758	                    return name.startsWith(CACHE_PREFIX);
759	                }
760	            });
761	            if (files == null || files.length <= 0) return true;
762	            boolean flag = true;
763	            for (File file : files) {
764	                if (!file.delete()) {
765	                    flag = false;
766	                    continue;
767	                }
768	                cacheSize.addAndGet(-file.length());
769	                cacheCount.addAndGet(-1);
770	                lastUsageDates.remove(file);
771	            }
772	            if (flag) {
773	                lastUsageDates.clear();
774	                cacheSize.set(0);
775	                cacheCount.set(0);
776	            }
777	            return flag;
778	        }
779	
780	        /**
781	         * Remove the oldest files.
782	         *
783	         * @return the size of oldest files, in bytes
784	         */
785	        private long removeOldest() {
786	            if (lastUsageDates.isEmpty()) return 0;
787	            Long oldestUsage = Long.MAX_VALUE;
788	            File oldestFile = null;
789	            Set<Map.Entry<File, Long>> entries = lastUsageDates.entrySet();
790	            synchronized (lastUsageDates) {
791	                for (Map.Entry<File, Long> entry : entries) {
792	                    Long lastValueUsage = entry.getValue();
793	                    if (lastValueUsage < oldestUsage) {
794	                        oldestUsage = lastValueUsage;
795	                        oldestFile = entry.getKey();
796	                    }
797	                }
798	            }
799	            if (oldestFile == null) return 0;
800	            long fileSize = oldestFile.length();
801	            if (oldestFile.delete()) {
802	                lastUsageDates.remove(oldestFile);
803	                return fileSize;
804	            }
805	            return 0;
806	        }
807	    }
808	
809	    private static final class DiskCacheHelper {
810	
811	        static final int TIME_INFO_LEN = 14;
812	
813	        private static byte[] newByteArrayWithTime(final int second, final byte[] data) {
814	            byte[] time = createDueTime(second).getBytes();
815	            byte[] content = new byte[time.length + data.length];
816	            System.arraycopy(time, 0, content, 0, time.length);
817	            System.arraycopy(data, 0, content, time.length, data.length);
818	            return content;
819	        }
820	
821	        /**
822	         * Return the string of due time.
823	         *
824	         * @param seconds The seconds.
825	         * @return the string of due time
826	         */
827	        private static String createDueTime(final int seconds) {
828	            return String.format(
829	                    Locale.getDefault(), "_$%010d$_",
830	                    System.currentTimeMillis() / 1000 + seconds
831	            );
832	        }
833	
834	        private static boolean isDue(final byte[] data) {
835	            long millis = getDueTime(data);
836	            return millis != -1 && System.currentTimeMillis() > millis;
837	        }
838	
839	        private static long getDueTime(final byte[] data) {
840	            if (hasTimeInfo(data)) {
841	                String millis = new String(copyOfRange(data, 2, 12));
842	                try {
843	                    return Long.parseLong(millis) * 1000;
844	                } catch (NumberFormatException e) {
845	                    return -1;
846	                }
847	            }
848	            return -1;
849	        }
850	
851	        private static byte[] getDataWithoutDueTime(final byte[] data) {
852	            if (hasTimeInfo(data)) {
853	                return copyOfRange(data, TIME_INFO_LEN, data.length);
854	            }
855	            return data;
856	        }
857	
858	        private static byte[] copyOfRange(final byte[] original, final int from, final int to) {
859	            int newLength = to - from;
860	            if (newLength < 0) throw new IllegalArgumentException(from + " > " + to);
861	            byte[] copy = new byte[newLength];
862	            System.arraycopy(original, from, copy, 0, Math.min(original.length - from, newLength));
863	            return copy;
864	        }
865	
866	        private static boolean hasTimeInfo(final byte[] data) {
867	            return data != null
868	                    && data.length >= TIME_INFO_LEN
869	                    && data[0] == '_'
870	                    && data[1] == '$'
871	                    && data[12] == '$'
872	                    && data[13] == '_';
873	        }
874	    }
875	}

