3	import androidx.annotation.NonNull;
4	import androidx.collection.LruCache;
5	
6	import com.blankj.utilcode.constant.CacheConstants;
7	
8	import java.util.HashMap;
9	import java.util.Map;
10	
11	/**
12	 * <pre>
13	 *     author: Blankj
14	 *     blog  : http://blankj.com
15	 *     time  : 2017/05/24
16	 *     desc  : utils about memory cache
17	 * </pre>
18	 */
19	public final class CacheMemoryUtils implements CacheConstants {
20	
21	    private static final int DEFAULT_MAX_COUNT = 256;
22	
23	    private static final Map<String, CacheMemoryUtils> CACHE_MAP = new HashMap<>();
24	
25	    private final String                       mCacheKey;
26	    private final LruCache<String, CacheValue> mMemoryCache;
27	
28	    /**
29	     * Return the single {@link CacheMemoryUtils} instance.
30	     *
31	     * @return the single {@link CacheMemoryUtils} instance
32	     */
33	    public static CacheMemoryUtils getInstance() {
34	        return getInstance(DEFAULT_MAX_COUNT);
35	    }
36	
37	    /**
38	     * Return the single {@link CacheMemoryUtils} instance.
39	     *
40	     * @param maxCount The max count of cache.
41	     * @return the single {@link CacheMemoryUtils} instance
42	     */
43	    public static CacheMemoryUtils getInstance(final int maxCount) {
44	        return getInstance(String.valueOf(maxCount), maxCount);
45	    }
46	
47	    /**
48	     * Return the single {@link CacheMemoryUtils} instance.
49	     *
50	     * @param cacheKey The key of cache.
51	     * @param maxCount The max count of cache.
52	     * @return the single {@link CacheMemoryUtils} instance
53	     */
54	    public static CacheMemoryUtils getInstance(final String cacheKey, final int maxCount) {
55	        CacheMemoryUtils cache = CACHE_MAP.get(cacheKey);
56	        if (cache == null) {
57	            synchronized (CacheMemoryUtils.class) {
58	                cache = CACHE_MAP.get(cacheKey);
59	                if (cache == null) {
60	                    cache = new CacheMemoryUtils(cacheKey, new LruCache<String, CacheValue>(maxCount));
61	                    CACHE_MAP.put(cacheKey, cache);
62	                }
63	            }
64	        }
65	        return cache;
66	    }
67	
68	    private CacheMemoryUtils(String cacheKey, LruCache<String, CacheValue> memoryCache) {
69	        mCacheKey = cacheKey;
70	        mMemoryCache = memoryCache;
71	    }
72	
73	    @Override
74	    public String toString() {
75	        return mCacheKey + "@" + Integer.toHexString(hashCode());
76	    }
77	
78	    /**
79	     * Put bytes in cache.
80	     *
81	     * @param key   The key of cache.
82	     * @param value The value of cache.
83	     */
84	    public void put(@NonNull final String key, final Object value) {
85	        put(key, value, -1);
86	    }
87	
88	    /**
89	     * Put bytes in cache.
90	     *
91	     * @param key      The key of cache.
92	     * @param value    The value of cache.
93	     * @param saveTime The save time of cache, in seconds.
94	     */
95	    public void put(@NonNull final String key, final Object value, int saveTime) {
96	        if (value == null) return;
97	        long dueTime = saveTime < 0 ? -1 : System.currentTimeMillis() + saveTime * 1000;
98	        mMemoryCache.put(key, new CacheValue(dueTime, value));
99	    }
100	
101	    /**
102	     * Return the value in cache.
103	     *
104	     * @param key The key of cache.
105	     * @param <T> The value type.
106	     * @return the value if cache exists or null otherwise
107	     */
108	    public <T> T get(@NonNull final String key) {
109	        return get(key, null);
110	    }
111	
112	    /**
113	     * Return the value in cache.
114	     *
115	     * @param key          The key of cache.
116	     * @param defaultValue The default value if the cache doesn't exist.
117	     * @param <T>          The value type.
118	     * @return the value if cache exists or defaultValue otherwise
119	     */
120	    public <T> T get(@NonNull final String key, final T defaultValue) {
121	        CacheValue val = mMemoryCache.get(key);
122	        if (val == null) return defaultValue;
123	        if (val.dueTime == -1 || val.dueTime >= System.currentTimeMillis()) {
124	            //noinspection unchecked
125	            return (T) val.value;
126	        }
127	        mMemoryCache.remove(key);
128	        return defaultValue;
129	    }
130	
131	    /**
132	     * Return the count of cache.
133	     *
134	     * @return the count of cache
135	     */
136	    public int getCacheCount() {
137	        return mMemoryCache.size();
138	    }
139	
140	    /**
141	     * Remove the cache by key.
142	     *
143	     * @param key The key of cache.
144	     * @return {@code true}: success<br>{@code false}: fail
145	     */
146	    public Object remove(@NonNull final String key) {
147	        CacheValue remove = mMemoryCache.remove(key);
148	        if (remove == null) return null;
149	        return remove.value;
150	    }
151	
152	    /**
153	     * Clear all of the cache.
154	     */
155	    public void clear() {
156	        mMemoryCache.evictAll();
157	    }
158	
159	    private static final class CacheValue {
160	        long   dueTime;
161	        Object value;
162	
163	        CacheValue(long dueTime, Object value) {
164	            this.dueTime = dueTime;
165	            this.value = value;
166	        }
167	    }
168	}

