146	    /**
147	     * Write file from input stream.
148	     *
149	     * @param file     The file.
150	     * @param is       The input stream.
151	     * @param append   True to append, false otherwise.
152	     * @param listener The progress update listener.
153	     * @return {@code true}: success<br>{@code false}: fail
154	     */
155	    public static boolean writeFileFromIS(final File file,
156	                                          final InputStream is,
157	                                          final boolean append,
158	                                          final OnProgressUpdateListener listener) {
159	        if (is == null || !UtilsBridge.createOrExistsFile(file)) {
160	            Log.e("FileIOUtils", "create file <" + file + "> failed.");
161	            return false;
162	        }
163	        OutputStream os = null;
164	        try {
165	            os = new BufferedOutputStream(new FileOutputStream(file, append), sBufferSize);
166	            if (listener == null) {
167	                byte[] data = new byte[sBufferSize];
168	                for (int len; (len = is.read(data)) != -1; ) {
169	                    os.write(data, 0, len);
170	                }
171	            } else {
172	                double totalSize = is.available();
173	                int curSize = 0;
174	                listener.onProgressUpdate(0);
175	                byte[] data = new byte[sBufferSize];
176	                for (int len; (len = is.read(data)) != -1; ) {
177	                    os.write(data, 0, len);
178	                    curSize += len;
179	                    listener.onProgressUpdate(curSize / totalSize);
180	                }
181	            }
182	            return true;
183	        } catch (IOException e) {
184	            e.printStackTrace();
185	            return false;
186	        } finally {
187	            try {
188	                is.close();
189	            } catch (IOException e) {
190	                e.printStackTrace();
191	            }
192	            try {
193	                if (os != null) {
194	                    os.close();
195	                }
196	            } catch (IOException e) {
197	                e.printStackTrace();
198	            }
199	        }
200	    }
