761	    private static List<String> getAppSignaturesHash(final String packageName, final String algorithm) {
762	        ArrayList<String> result = new ArrayList<>();
763	        if (UtilsBridge.isSpace(packageName)) return result;
764	        Signature[] signatures = getAppSignatures(packageName);
765	        if (signatures == null || signatures.length <= 0) return result;
766	        for (Signature signature : signatures) {
767	            String hash = UtilsBridge.bytes2HexString(UtilsBridge.hashTemplate(signature.toByteArray(), algorithm))
768	                    .replaceAll("(?<=[0-9A-F]{2})[0-9A-F]{2}", ":$0");
769	            result.add(hash);
770	        }
771	        return result;
772	    }
