888	    private static AppInfo getBean(final PackageManager pm, final PackageInfo pi) {
889	        if (pi == null) return null;
890	        String versionName = pi.versionName;
891	        int versionCode = pi.versionCode;
892	        String packageName = pi.packageName;
893	        ApplicationInfo ai = pi.applicationInfo;
894	        if (ai == null) {
895	            return new AppInfo(packageName, "", null, "", versionName, versionCode, -1, -1, false);
896	        }
897	        String name = ai.loadLabel(pm).toString();
898	        Drawable icon = ai.loadIcon(pm);
899	        String packagePath = ai.sourceDir;
900	        int minSdkVersion = -1;
901	        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
902	            minSdkVersion = ai.minSdkVersion;
903	        }
904	        int targetSdkVersion = ai.targetSdkVersion;
905	        boolean isSystem = (ApplicationInfo.FLAG_SYSTEM & ai.flags) != 0;
906	        return new AppInfo(packageName, name, icon, packagePath, versionName, versionCode, minSdkVersion, targetSdkVersion, isSystem);
907	    }
