421	    private static boolean copyOrMoveDir(final File srcDir,
422	                                         final File destDir,
423	                                         final OnReplaceListener listener,
424	                                         final boolean isMove) {
425	        if (srcDir == null || destDir == null) return false;
426	        // destDir's path locate in srcDir's path then return false
427	        String srcPath = srcDir.getPath() + File.separator;
428	        String destPath = destDir.getPath() + File.separator;
429	        if (destPath.contains(srcPath)) return false;
430	        if (!srcDir.exists() || !srcDir.isDirectory()) return false;
431	        if (!createOrExistsDir(destDir)) return false;
432	        File[] files = srcDir.listFiles();
433	        if (files != null && files.length > 0) {
434	            for (File file : files) {
435	                File oneDestFile = new File(destPath + file.getName());
436	                if (file.isFile()) {
437	                    if (!copyOrMoveFile(file, oneDestFile, listener, isMove)) return false;
438	                } else if (file.isDirectory()) {
439	                    if (!copyOrMoveDir(file, oneDestFile, listener, isMove)) return false;
440	                }
441	            }
442	        }
443	        return !isMove || deleteDir(srcDir);
444	    }
