446	    private static boolean copyOrMoveFile(final File srcFile,
447	                                          final File destFile,
448	                                          final OnReplaceListener listener,
449	                                          final boolean isMove) {
450	        if (srcFile == null || destFile == null) return false;
451	        // srcFile equals destFile then return false
452	        if (srcFile.equals(destFile)) return false;
453	        // srcFile doesn't exist or isn't a file then return false
454	        if (!srcFile.exists() || !srcFile.isFile()) return false;
455	        if (destFile.exists()) {
456	            if (listener == null || listener.onReplace(srcFile, destFile)) {// require delete the old file
457	                if (!destFile.delete()) {// unsuccessfully delete then return false
458	                    return false;
459	                }
460	            } else {
461	                return true;
462	            }
463	        }
464	        if (!createOrExistsDir(destFile.getParentFile())) return false;
465	        try {
466	            return UtilsBridge.writeFileFromIS(destFile.getAbsolutePath(), new FileInputStream(srcFile))
467	                    && !(isMove && !deleteFile(srcFile));
468	        } catch (FileNotFoundException e) {
469	            e.printStackTrace();
470	            return false;
471	        }
472	    }
