975	    /**
976	     * UTF-8编码方式
977	     * ----------------------------------------------
978	     * 0xxxxxxx
979	     * 110xxxxx 10xxxxxx
980	     * 1110xxxx 10xxxxxx 10xxxxxx
981	     * 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
982	     */
983	    private static int isUtf8(byte[] raw) {
984	        int i, len;
985	        int utf8 = 0, ascii = 0;
986	        if (raw.length > 3) {
987	            if ((raw[0] == (byte) 0xEF) && (raw[1] == (byte) 0xBB) && (raw[2] == (byte) 0xBF)) {
988	                return 100;
989	            }
990	        }
991	        len = raw.length;
992	        int child = 0;
993	        for (i = 0; i < len; ) {
994	            // UTF-8 byte shouldn't be FF and FE
995	            if ((raw[i] & (byte) 0xFF) == (byte) 0xFF || (raw[i] & (byte) 0xFE) == (byte) 0xFE) {
996	                return 0;
997	            }
998	            if (child == 0) {
999	                // ASCII format is 0x0*******
1000	                if ((raw[i] & (byte) 0x7F) == raw[i] && raw[i] != 0) {
1001	                    ascii++;
1002	                } else if ((raw[i] & (byte) 0xC0) == (byte) 0xC0) {
1003	                    // 0x11****** maybe is UTF-8
1004	                    for (int bit = 0; bit < 8; bit++) {
1005	                        if ((((byte) (0x80 >> bit)) & raw[i]) == ((byte) (0x80 >> bit))) {
1006	                            child = bit;
1007	                        } else {
1008	                            break;
1009	                        }
1010	                    }
1011	                    utf8++;
1012	                }
1013	                i++;
1014	            } else {
1015	                child = (raw.length - i > child) ? child : (raw.length - i);
1016	                boolean currentNotUtf8 = false;
1017	                for (int children = 0; children < child; children++) {
1018	                    // format must is 0x10******
1019	                    if ((raw[i + children] & ((byte) 0x80)) != ((byte) 0x80)) {
1020	                        if ((raw[i + children] & (byte) 0x7F) == raw[i + children] && raw[i] != 0) {
1021	                            // ASCII format is 0x0*******
1022	                            ascii++;
1023	                        }
1024	                        currentNotUtf8 = true;
1025	                    }
1026	                }
1027	                if (currentNotUtf8) {
1028	                    utf8--;
1029	                    i++;
1030	                } else {
1031	                    utf8 += child;
1032	                    i += child;
1033	                }
1034	                child = 0;
1035	            }
1036	        }
1037	        // UTF-8 contains ASCII
1038	        if (ascii == len) {
1039	            return 100;
1040	        }
1041	        return (int) (100 * ((float) (utf8 + ascii) / (float) len));
1042	    }
