1260	        DigestInputStream dis = null;
1261	        try {
1262	            FileInputStream fis = new FileInputStream(file);
1263	            MessageDigest md = MessageDigest.getInstance("MD5");
1264	            dis = new DigestInputStream(fis, md);
1265	            byte[] buffer = new byte[1024 * 256];
1266	            while (true) {
1267	                if (!(dis.read(buffer) > 0)) break;
1268	            }
1269	            md = dis.getMessageDigest();
1270	            return md.digest();
1271	        } catch (NoSuchAlgorithmException | IOException e) {
1272	            e.printStackTrace();
1273	        } finally {
1274	            try {
1275	                if (dis != null) {
1276	                    dis.close();
1277	                }
1278	            } catch (IOException e) {
1279	                e.printStackTrace();
1280	            }
1281	        }
1282	        return null;
