106	    @Nullable
107	    private static Activity getActivityByContextInner(@Nullable Context context) {
108	        if (context == null) return null;
109	        List<Context> list = new ArrayList<>();
110	        while (context instanceof ContextWrapper) {
111	            if (context instanceof Activity) {
112	                return (Activity) context;
113	            }
114	            Activity activity = getActivityFromDecorContext(context);
115	            if (activity != null) return activity;
116	            list.add(context);
117	            context = ((ContextWrapper) context).getBaseContext();
118	            if (context == null) {
119	                return null;
120	            }
121	            if (list.contains(context)) {
122	                // loop context
123	                return null;
124	            }
125	        }
126	        return null;
127	    }
