129	    @Nullable
130	    private static Activity getActivityFromDecorContext(@Nullable Context context) {
131	        if (context == null) return null;
132	        if (context.getClass().getName().equals("com.android.internal.policy.DecorContext")) {
133	            try {
134	                Field mActivityContextField = context.getClass().getDeclaredField("mActivityContext");
135	                mActivityContextField.setAccessible(true);
136	                //noinspection ConstantConditions,unchecked
137	                return ((WeakReference<Activity>) mActivityContextField.get(context)).get();
138	            } catch (Exception ignore) {
139	            }
140	        }
141	        return null;
142	    }
