1464	    /**
1465	     * Return the name of launcher activity.
1466	     *
1467	     * @param pkg The name of the package.
1468	     * @return the name of launcher activity
1469	     */
1470	    public static String getLauncherActivity(@NonNull final String pkg) {
1471	        if (UtilsBridge.isSpace(pkg)) return "";
1472	        Intent intent = new Intent(Intent.ACTION_MAIN, null);
1473	        intent.addCategory(Intent.CATEGORY_LAUNCHER);
1474	        intent.setPackage(pkg);
1475	        PackageManager pm = Utils.getApp().getPackageManager();
1476	        List<ResolveInfo> info = pm.queryIntentActivities(intent, 0);
1477	        if (info == null || info.size() == 0) {
1478	            return "";
1479	        }
1480	        return info.get(0).activityInfo.name;
1481	    }
