1492	    /**
1493	     * Return the list of main activities.
1494	     *
1495	     * @param pkg The name of the package.
1496	     * @return the list of main activities
1497	     */
1498	    public static List<String> getMainActivities(@NonNull final String pkg) {
1499	        List<String> ret = new ArrayList<>();
1500	        Intent intent = new Intent(Intent.ACTION_MAIN, null);
1501	        intent.setPackage(pkg);
1502	        PackageManager pm = Utils.getApp().getPackageManager();
1503	        List<ResolveInfo> info = pm.queryIntentActivities(intent, 0);
1504	        int size = info.size();
1505	        if (size == 0) return ret;
1506	        for (int i = 0; i < size; i++) {
1507	            ResolveInfo ri = info.get(i);
1508	            if (ri.activityInfo.processName.equals(pkg)) {
1509	                ret.add(ri.activityInfo.name);
1510	            }
1511	        }
1512	        return ret;
1513	    }
