1997	    private static boolean startActivity(final Intent intent,
1998	                                         final Context context,
1999	                                         final Bundle options) {
2000	        if (!(context instanceof Activity)) {
2001	            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
2002	        }
2003	        try {
2004	            if (options != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.JELLY_BEAN) {
2005	                context.startActivity(intent, options);
2006	            } else {
2007	                context.startActivity(intent);
2008	            }
2009	        } catch (Exception e) {
2010	            Log.e("ActivityUtils", "An exception occurred in startActivity, error message: " + e.getLocalizedMessage());
2011	            return false;
2012	        }
2013	        return true;
2014	    }
