2114	    private static Bundle getOptionsBundle(final Activity activity,
2115	                                           final View[] sharedElements) {
2116	        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.LOLLIPOP) return null;
2117	        if (sharedElements == null) return null;
2118	        int len = sharedElements.length;
2119	        if (len <= 0) return null;
2120	        @SuppressWarnings("unchecked")
2121	        Pair<View, String>[] pairs = new Pair[len];
2122	        for (int i = 0; i < len; i++) {
2123	            pairs[i] = Pair.create(sharedElements[i], sharedElements[i].getTransitionName());
2124	        }
2125	        return ActivityOptionsCompat.makeSceneTransitionAnimation(activity, pairs).toBundle();
2126	    }
